import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

tanh_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>

__global__ void tanh_kernel_vec4(const float4* __restrict__ input,
                                  float4* __restrict__ output,
                                  int64_t n_vec4) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    #pragma unroll 4
    for (int64_t i = idx; i < n_vec4; i += stride) {
        float4 in = __ldg(&input[i]);
        float4 out;
        out.x = tanhf(in.x);
        out.y = tanhf(in.y);
        out.z = tanhf(in.z);
        out.w = tanhf(in.w);
        output[i] = out;
    }
}
__global__ void tanh_kernel_scalar(const float* __restrict__ input,
                                    float* __restrict__ output,
                                    int64_t n) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    #pragma unroll 4
    for (int64_t i = idx; i < n; i += stride) {
        output[i] = tanhf(__ldg(&input[i]));
    }
}

torch::Tensor tanh_cuda(torch::Tensor x) {
    auto x_contig = x.contiguous();
    auto output = torch::empty_like(x_contig);

    int64_t n = x_contig.numel();
    const int threads = 256;

    if (n % 4 == 0) {
        int64_t n_vec4 = n / 4;
        int blocks = (int)std::min<int64_t>((n_vec4 + threads - 1) / threads, 65535 * 4);
        if (blocks < 1) blocks = 1;

        tanh_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(x_contig.data_ptr<float>()),
            reinterpret_cast<float4*>(output.data_ptr<float>()),
            n_vec4
        );
    } else {
        int blocks = (int)std::min<int64_t>((n + threads - 1) / threads, 65535 * 4);
        if (blocks < 1) blocks = 1;

        tanh_kernel_scalar<<<blocks, threads>>>(
            x_contig.data_ptr<float>(),
            output.data_ptr<float>(),
            n
        );
    }

    return output;
}
"""

tanh_cpp_source = "torch::Tensor tanh_cuda(torch::Tensor x);"

tanh_module = load_inline(
    name="tanh_module",
    cpp_sources=tanh_cpp_source,
    cuda_sources=tanh_source,
    functions=["tanh_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a Tanh activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.tanh_op = tanh_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.tanh_op.tanh_cuda(x)


batch_size = 4096
dim = 131072


def get_inputs():
    x = torch.rand(batch_size, dim)
    return [x]


def get_init_inputs():
    return []

